detect_missed_issue.source:
def detect_missed_issue(code: str) -> str:
    try:
        tree = ast.parse(code)
        issues = []
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                if not node.body and not node.decorator_list:
                    issues.append(f"Empty function: {node.name}")
            elif isinstance(node, ast.If):
                if not node.test and not node.orelse:
                    issues.append("Unconditional block (if without condition)")
            elif isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == 'x':
                        issues.append(f"Unused variable assignment: {target.id}")
        return f"Potential missed issues: {', '.join(issues[:3])}" if issues else "No obvious missed issues"
    except:
        return "Could not analyze code structure"

detect_good.source:
def detect_good(code: str) -> str:
    try:
        tree = ast.parse(code)
        functions = [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]
        return f"Good code: {len(functions)} functions, {len([n for n in ast.walk(tree) if isinstance(n, ast.ClassDef)])} classes"
    except:
        return "Good code: No parseable structure found"

